class WholesaleReturnFinanceRow {
  final String returnId,businessName,invoiceId,invoiceNumber,returnStatus,returnReason,creditNoteId,creditNumber,financeStatus;
  final double physicalReturnValue,creditAmount,invoicePaidAmount,invoiceNetTotal,customerCreditBalance,refundsPaid,refundDue;
  const WholesaleReturnFinanceRow({required this.returnId,required this.businessName,required this.invoiceId,required this.invoiceNumber,required this.returnStatus,required this.returnReason,required this.physicalReturnValue,required this.creditNoteId,required this.creditNumber,required this.creditAmount,required this.invoicePaidAmount,required this.invoiceNetTotal,required this.customerCreditBalance,required this.refundsPaid,required this.refundDue,required this.financeStatus});
  factory WholesaleReturnFinanceRow.fromSupabase(Map<String,dynamic>d){double n(dynamic v)=>v is num?v.toDouble():double.tryParse(v?.toString()??'')??0;return WholesaleReturnFinanceRow(returnId:(d['return_id']??'').toString(),businessName:(d['business_name']??'Wholesale business').toString(),invoiceId:(d['invoice_id']??'').toString(),invoiceNumber:(d['invoice_number']??'').toString(),returnStatus:(d['return_status']??'').toString(),returnReason:(d['return_reason']??'').toString(),physicalReturnValue:n(d['physical_return_value']),creditNoteId:(d['credit_note_id']??'').toString(),creditNumber:(d['credit_number']??'').toString(),creditAmount:n(d['credit_amount']),invoicePaidAmount:n(d['invoice_paid_amount']),invoiceNetTotal:n(d['invoice_net_total']),customerCreditBalance:n(d['customer_credit_balance']),refundsPaid:n(d['refunds_paid']),refundDue:n(d['refund_due']),financeStatus:(d['finance_status']??'needs_credit').toString());}
}
class WholesaleRefundRow {
  final String id,refundNumber,creditNoteId,creditNumber,invoiceId,invoiceNumber,businessName,paymentMethod,paymentReference,status,notes; final double amount; final DateTime? paidAt;
  const WholesaleRefundRow({required this.id,required this.refundNumber,required this.creditNoteId,required this.creditNumber,required this.invoiceId,required this.invoiceNumber,required this.businessName,required this.amount,required this.paymentMethod,required this.paymentReference,required this.status,required this.paidAt,required this.notes});
  factory WholesaleRefundRow.fromSupabase(Map<String,dynamic>d){double n(dynamic v)=>v is num?v.toDouble():double.tryParse(v?.toString()??'')??0;return WholesaleRefundRow(id:(d['refund_id']??'').toString(),refundNumber:(d['refund_number']??'').toString(),creditNoteId:(d['credit_note_id']??'').toString(),creditNumber:(d['credit_number']??'').toString(),invoiceId:(d['invoice_id']??'').toString(),invoiceNumber:(d['invoice_number']??'').toString(),businessName:(d['business_name']??'Wholesale business').toString(),amount:n(d['amount']),paymentMethod:(d['payment_method']??'').toString(),paymentReference:(d['payment_reference']??'').toString(),status:(d['status']??'paid').toString(),paidAt:DateTime.tryParse((d['paid_at']??'').toString()),notes:(d['notes']??'').toString());}
}
Future<List<WholesaleReturnFinanceRow>> fetchWholesaleReturnFinance({String status='all'}) async {await requireAdminAccess();final r=await supabase.rpc('admin_list_return_finance',params:{'p_status':status,'p_limit':200});return (r as List).map((x)=>WholesaleReturnFinanceRow.fromSupabase(Map<String,dynamic>.from(x as Map))).toList();}
Future<List<WholesaleRefundRow>> fetchWholesaleRefunds() async {await requireAdminAccess();final r=await supabase.rpc('admin_list_wholesale_refunds',params:{'p_limit':200});return (r as List).map((x)=>WholesaleRefundRow.fromSupabase(Map<String,dynamic>.from(x as Map))).toList();}
Future<void> recordWholesaleRefund({required String creditNoteId,required double amount,required String method,required String reference,String notes=''}) async {await requireAdminAccess();await supabase.rpc('admin_record_wholesale_refund',params:{'p_credit_note_id':creditNoteId,'p_amount':amount,'p_payment_method':method.trim(),'p_payment_reference':reference.trim(),'p_notes':notes.trim()});}

class WholesaleReturnFinanceScreen extends StatefulWidget{const WholesaleReturnFinanceScreen({super.key});@override State<WholesaleReturnFinanceScreen> createState()=>_WholesaleReturnFinanceScreenState();}
