  late Future<List<dynamic>> _future;String _status='all';@override void initState(){super.initState();_future=_load();}Future<List<dynamic>> _load()=>Future.wait<dynamic>([fetchWholesaleReturnFinance(status:_status),fetchWholesaleRefunds()]);Future<void> _refresh()async{final n=_load();setState(()=>_future=n);await n;}
