mount.dispose();reference.dispose();notes.dispose();}
  @override Widget build(BuildContext context)=>Scaffold(backgroundColor:FarmColors.background,appBar:AppBar(title:const Text('Return Finance & Refunds')),body:FutureBuilder<List<dynamic>>(future:_future,builder:(context,s){if(s.connectionState==ConnectionState.waiting&&s.data==null)return const Center(child:CircularProgressIndicator());if(s.hasError&&s.data==null)return Center(child:Text(friendlyAppError(s.error!)));final d=s.data??const<dynamic>[];final rows=d.isNotEmpty?d[0] as List<WholesaleReturnFinanceRow>:<WholesaleReturnFinanceRow>[];final refunds=d.length>1?d[1] as List<WholesaleRefundRow>:<WholesaleRefundRow>[];return RefreshIndicator(onRefresh:_refresh,child:ListView(physics:const AlwaysScrollableScrollPhysics(),padding:const EdgeInsets.fromLTRB(16,16,16,110),children:[
    const FarmCard(padding:EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Return-to-cash reconciliation',style:TextStyle(fontSize:17,fontWeight:FontWeight.w900)),SizedBox(height:4),Text('A credit note reduces the sale. A refund is recorded only when confirmed payments create a customer credit balance.',style:TextStyle(color:FarmColors.mutedText,fontSize:10.5,height:1.35,fontWeight:FontWeight.w600))])),const SizedBox(height:12),SingleChildScrollView(scrollDirection:Axis.horizontal,child:Row(children:{'all':'All','needs_credit':'Needs Credit','refund_due':'Refund Due','settled':'Settled'}.entries.map((e)=>Padding(padding:const EdgeInsets.only(right:7),child:ChoiceChip(label:Text(e.value),selected:_status==e.key,onSelected:(_){setState((){_status=e.key;_future=_load();});}))).toList())),const SizedBox(height:12),
    if(rows.isEmpty)const FarmEmptyState(icon:Icons.assignment_return_outlined,title:'No return finance rows',message:'Delivered returns will appear here when finance review is required.')else ...rows.map((r)=>Padding(padding:const EdgeInsets.only(bottom:9),child:FarmCard(padding:const EdgeInsets.all(13),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Expanded(child:Text('${r.invoiceNumber} • ${r.businessName}',style:const TextStyle(fontWeight:FontWeight.w900))),Text(r.financeStatus.replaceAll('_',' ').toUpperCase(),style:TextStyle(color:_color(r.financeStatus),fontSize:9,fontWeight:FontWeight.w900))]),const SizedBox(height:6),Text('Return ${formatJmd(r.physicalReturnValue)} • Credit ${formatJmd(r.creditAmount)} • Paid ${formatJmd(r.invoicePaidAmount)}',style:const TextStyle(color:FarmColors.mutedText,fontSize:10,fontWeight:FontWeight.w700)),if(r.refundDue>0.005)...[const SizedBox(height:8),OutlinedButton.icon(onPressed:r.creditNoteId.isEmpty?null:()=>_refund(r),icon:const Icon(Icons.payments_outlined,size:16),label:Text('Refund ${formatJmd(r.refundDue)}'))]])))),const SizedBox(height:18),const Text('Refund History',style:TextStyle(fontSize:16,fontWeight:FontWeight.w900)),const SizedBox(height:8),if(refunds.isEmpty)const FarmCard(child:Text('No customer refunds recorded.'))else ...refunds.take(40).map((r)=>Padding(padding:const EdgeInsets.only(bottom:8),child:FarmCard(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${r.refundNumber} • ${r.businessName}',style:const TextStyle(fontWeight:FontWeight.w900)),Text('${r.creditNumber} • ${r.paymentMethod} • ${r.paymentReference}',style:const TextStyle(color:FarmColors.mutedText,fontSize:9.8,fontWeight:FontWeight.w700))])),Text(formatJmd(r.amount),style:const TextStyle(fontWeight:FontWeight.w900))]))))
